mapper.select:
select t.org_month_amount orgMonthAmount,t.month_amount monthAmount,t.staff_name staffName,t.ft_id ftId,t.log_id
logId,t.status_cd statusCd,t.ft_name ftName,t.community_id communityId,t.create_time createTime
from fee_type_log t
where 1 =1

    and t.org_month_amount= #{orgMonthAmount}


    and t.month_amount= #{monthAmount}


    and t.staff_name= #{staffName}


    and t.ft_id= #{ftId}


    and t.log_id= #{logId}


    and t.status_cd= #{statusCd}


    and t.ft_name= #{ftName}


    and t.community_id= #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

